+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.Arrays;
+import java.util.Locale;
+import java.util.Set;
+
+/**
+ * Name and status filter. Name terms must each occur in first or last name,
+ * ignoring case and accents; empty statuses means all statuses.
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    public static final CustomerFilter NONE = new CustomerFilter("", Set.of());
+
+    public CustomerFilter {
+        name = name == null ? "" : name;
+        statuses = statuses == null ? Set.of() : Set.copyOf(statuses);
+    }
+
+    public boolean matches(Customer c) {
+        if (!statuses.isEmpty() && !statuses.contains(c.status())) {
+            return false;
+        }
+        String trimmed = name.strip();
+        if (trimmed.isEmpty()) {
+            return true;
+        }
+        String first = fold(c.firstName());
+        String last = fold(c.lastName());
+        return Arrays.stream(fold(trimmed).split("(?U)\\s+"))
+                .allMatch(t -> first.contains(t) || last.contains(t));
+    }
+
+    static String fold(String s) {
+        return Normalizer.normalize(s, Normalizer.Form.NFD)
+                .replaceAll("\\p{M}+", "")
+                .toLowerCase(Locale.ROOT);
+    }
+}
